import type { DownloadOptions, SerializedExcel } from './types';
import { ExcelError, checkAbort, config, phase } from './errors';
import { serializeExcel } from './export';

function validateFileName(fileName: string): void {
  config(
    typeof fileName === 'string' &&
      fileName.trim().length > 0 &&
      !/[\\/]/.test(fileName) &&
      !Array.from(fileName).some(character => character.charCodeAt(0) < 32),
    'Invalid file name'
  );
  config(
    fileName.replace(/\.(xlsx|xls|csv)$/i, '').length > 0,
    'File name requires a stem'
  );
}

/** Saves already-generated bytes; only this function accesses browser globals. */
export function saveExcelFile(
  file: SerializedExcel,
  fileName: string,
  signal?: AbortSignal
): void {
  checkAbort(signal);
  if (
    typeof document === 'undefined' ||
    typeof URL?.createObjectURL !== 'function'
  )
    throw new ExcelError(
      'BROWSER_REQUIRED',
      'File download requires a browser'
    );
  validateFileName(fileName);
  const stem = fileName.replace(/\.(xlsx|xls|csv)$/i, '');
  config(stem.length > 0, 'File name requires a stem');
  const blob = new Blob([new Uint8Array(file.bytes)], { type: file.mimeType });
  const anchor = document.createElement('a');
  const url = URL.createObjectURL(blob);
  try {
    anchor.href = url;
    anchor.download = `${stem}.${file.extension}`;
    anchor.style.display = 'none';
    document.body.appendChild(anchor);
    checkAbort(signal);
    anchor.click();
  } finally {
    anchor.remove();
    // Allow navigation to consume the URL before releasing it.
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
}
export async function downloadExcel<T extends object>(
  options: DownloadOptions<T>
): Promise<void> {
  // Fail before expensive file generation when the environment/name is invalid.
  validateFileName(options.fileName);
  if (typeof document === 'undefined')
    throw new ExcelError(
      'BROWSER_REQUIRED',
      'File download requires a browser'
    );
  const file = await serializeExcel(options);
  phase(options, 'downloading');
  saveExcelFile(file, options.fileName, options.signal);
}
